                if hi > lo:
                    touching = True
                    for yy in range(lo, hi):
                        if a[yy - y][-1] != b[yy - ny][0]:
                            return None
                        total_accent += a[yy - y][-1] != base
                    total_len += hi - lo
            elif nx + bw == x:
